func newReflection() unsafe.Pointer { return unsafe.Pointer(new(agentreflection.Reflection)) }

func newNReflection(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]agentreflection.Reflection, n)))
}

func ptrReflection(p unsafe.Pointer, c int32) any {
	r := (*agentreflection.Reflection)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 4:
		return (*string)(unsafe.Pointer(&r.SubjectType))
	case 5:
		return (**string)(unsafe.Pointer(&r.ThreadID))
	case 6:
		return (**string)(unsafe.Pointer(&r.RunID))
	case 7:
		return (**string)(unsafe.Pointer(&r.UserID))
	case 8:
		return (*int64)(unsafe.Pointer(&r.FromSequence))
	case 9:
		return (*int64)(unsafe.Pointer(&r.ThroughSequence))
	case 10:
		return (*string)(unsafe.Pointer(&r.Status))
	case 11:
		return (*string)(unsafe.Pointer(&r.SkipReason))
	case 12:
		return &r.Signals
	case 13:
		return &r.Changes
	case 14:
		return &r.Notes
	case 15:
		return &r.Tainted
	case 16:
		return &r.Model
	case 17:
		return (*string)(unsafe.Pointer(&r.ProviderID))
	case 18:
		return (*int64)(unsafe.Pointer(&r.InputTokens))
	case 19:
		return (*int64)(unsafe.Pointer(&r.OutputTokens))
	case 20:
		return &r.ErrorMessage
	case 21:
		return &r.FinishedAt
	case 22:
		return &r.Version
	case 23:
		return &r.CreatedAt
	case 24:
		return &r.UpdatedAt
	}
	return nil
}

func valueReflection(p unsafe.Pointer, c int32) any {
	r := (*agentreflection.Reflection)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.AgentDefinitionID)
	case 4:
		return string(r.SubjectType)
	case 5:
		if r.ThreadID == nil {
			return nil
		}
		return string(*r.ThreadID)
	case 6:
		if r.RunID == nil {
			return nil
		}
		return string(*r.RunID)
	case 7:
		if r.UserID == nil {
			return nil
		}
		return string(*r.UserID)
	case 8:
		return int64(r.FromSequence)
	case 9:
		return int64(r.ThroughSequence)
	case 10:
		return string(r.Status)
	case 11:
		if r.SkipReason == "" {
			return nil
		}
		return string(r.SkipReason)
	case 12:
		if r.Signals == nil {
			return keel.EmptyJSONArray
		}
		return r.Signals
	case 13:
		if r.Changes == nil {
			return keel.EmptyJSONArray
		}
		return r.Changes
	case 14:
		if r.Notes == "" {
			return nil
		}
		return r.Notes
	case 15:
		return r.Tainted
	case 16:
		if r.Model == "" {
			return nil
		}
		return r.Model
	case 17:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 18:
		return int64(r.InputTokens)
	case 19:
		return int64(r.OutputTokens)
	case 20:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 21:
		if r.FinishedAt == nil {
			return nil
		}
		return *r.FinishedAt
	case 22:
		return r.Version
	case 23:
		return r.CreatedAt
	case 24:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateReflection(ctx context.Context, p unsafe.Pointer) error {
	return (*agentreflection.Reflection)(p).BeforeCreate(ctx)
}

